@namespace sv_0208e12a6b8a4f5a8c4ec44532dbc623.Components.Pages.Settings
@using sv_0208e12a6b8a4f5a8c4ec44532dbc623.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings...</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <!-- Theme -->
                <div class="mb-4">
                    <h6 class="fw-semibold mb-2">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h6 class="fw-semibold mb-2">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6 class="fw-semibold mb-2">Language</h6>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                               checked="@_compactMode"
                               @onchange="e => _compactMode = (bool)e.Value!" />
                        <label class="form-check-label fw-semibold" for="compactMode">Compact Mode</label>
                    </div>
                    <small class="text-muted">Reduces spacing and padding throughout the UI.</small>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-6">
                <h6 class="fw-semibold mb-2">Live Preview</h6>
                <div class="appearance-preview border rounded @PreviewThemeClass"
                     style="@PreviewStyle">
                    <div class="preview-header">
                        <span class="fw-bold">Settings Dashboard</span>
                    </div>
                    <div class="preview-body">
                        <p class="mb-2">This is how your interface will look with the selected settings.</p>
                        <div class="d-flex gap-2 mb-2">
                            <span class="badge preview-badge">Profile</span>
                            <span class="badge preview-badge">Notifications</span>
                        </div>
                        <p class="preview-secondary mb-0">
                            Theme: @_theme · Font: @_fontSize · @(_compactMode ? "Compact" : "Comfortable")
                        </p>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private string? _successMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _successMessage = "Appearance settings saved!";
    }

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewStyle
    {
        get
        {
            var size = _fontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.15rem",
                _ => "1rem"
            };
            var padding = _compactMode ? "0.5rem" : "1rem";
            return $"font-size: {size}; --preview-padding: {padding};";
        }
    }
}

