@page "/settings"
@using sv_0208e12a6b8a4f5a8c4ec44532dbc623.Components.Pages.Settings

@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 70px);
    gap: 0;
}

::deep .settings-sidebar {
    width: 240px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding-top: 1rem;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.625rem 1rem;
    transition: background-color 0.15s, color 0.15s;
    border: none;
    background: none;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

::deep .sidebar-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 900px;
}

::deep .settings-section {
    animation: fadeIn 0.2s ease-in;
}

/* Appearance preview styles */
::deep .appearance-preview {
    overflow: hidden;
    transition: all 0.2s ease;
}

::deep .preview-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
}

::deep .preview-header {
    padding: var(--preview-padding, 1rem);
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

::deep .preview-body {
    padding: var(--preview-padding, 1rem);
}

::deep .preview-light .preview-badge {
    background-color: #e9ecef;
    color: #495057;
}

::deep .preview-dark .preview-badge {
    background-color: #313244;
    color: #cdd6f4;
}

::deep .preview-light .preview-secondary {
    color: #6c757d;
}

::deep .preview-dark .preview-secondary {
    color: #a6adc8;
}

/* Avatar preview */
::deep .avatar-preview {
    display: inline-block;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 50%;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

